def clean(s):return str(s).replace('\u2011','-').replace('\u2013','-').replace('\u2014','-').replace('\u2265','>=').replace('\u2264','<=')
def P(t,sty='body'):return Paragraph(escape(clean(t)).replace('\n','<br/>'),styles[sty])
def footer(canvas,d):
 canvas.setStrokeColor(GOLD);canvas.line(44,44,551,44)
 canvas.setFont('TY',8);canvas.setFillColor(INK);canvas.drawString(44,30,'TÉCNICOYA HUANCAYO | Documentación v2.0 | '+DATE)
 canvas.drawRightString(551,30,str(d.page))
 canvas.setFont('TY-Bold',8);canvas.drawString(44,809,'INGENIERÍA DE SOFTWARE / PRUEBAS Y CALIDAD')
def build(d,path):
 flow=[]
 for i,pg in enumerate(d['pages']):
  if i:flow.append(PageBreak())
  flow += [P(d['title'],'small'),Spacer(1,6),P(pg['title'],'h1')]
  for s in pg['sections']:
   flow.append(P(s['title'],'h2'))
   if 'text' in s:flow.append(P(s['text']))
   else:
    assert all(len(row)==len(s['heads']) for row in s['rows']), (d['name'],s['title'])
    count=len(s['heads']); widths={2:[150,357],3:[110,181,216],4:[100,130,145,132]}.get(count,[507/count]*count)
    if s['heads']==['Campo / tipo','Nulo','Regla / significado']:widths=[142,40,325]
    rows=[[P(x,'th') for x in s['heads']]]+[[P(x,'cell') for x in row] for row in s['rows']]
    t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),INK),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#f0f5f4'),colors.white]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),.3,colors.HexColor('#dce5e3'))]))
    flow.extend([t,Spacer(1,8)])
 SimpleDocTemplate(str(path),pagesize=(595.28,841.89),leftMargin=44,rightMargin=44,topMargin=52,bottomMargin=59,title=d['title'],author='Equipo TécnicoYa Huancayo',pageCompression=1).build(flow,onFirstPage=footer,onLaterPages=footer)

